package com.orderflow.notification.service;import com.orderflow.events.EventMetadata;import java.sql.Timestamp;import java.time.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;@Repository public class ProcessedEventStore{private final JdbcTemplate j;private final Clock c;public ProcessedEventStore(JdbcTemplate j,Clock c){this.j=j;this.c=c;}public boolean contains(EventMetadata m,String n){Integer x=j.queryForObject("SELECT count(*) FROM processed_event WHERE event_id=? AND consumer_name=?",Integer.class,m.eventId(),n);return x!=null&&x>0;}public void add(EventMetadata m,String n){j.update("INSERT INTO processed_event(event_id,event_type,aggregate_id,consumer_name,processed_at,correlation_id)VALUES(?,?,?,?,?,?)",m.eventId(),m.eventType().name(),m.aggregateId(),n,Timestamp.from(Instant.now(c)),m.correlationId());}}
